#!/usr/bin/env bash
# export-vm.sh — resets this box to a "never been played" state (fresh
# CTF_SECRET generated by whoever boots it, not the secret used during
# our own build/verify pass), snapshots that state, then flattens it
# into one standalone qcow2.
#
# This step matters MORE than it did for a static-flag VM: this
# series' flags are derived from a per-deployment CTF_SECRET. If we
# exported the disk as-is after verify.sh, every copy of this OVA
# would ship with the SAME secret (ours) and therefore the SAME
# flags -- defeating the entire point. Wiping .env here means each
# player's own first boot (via the ctf-box.service unit) generates
# their own fresh secret, same as a Docker player running ./start.sh.
set -euo pipefail
cd "$(dirname "$0")/.."

KEY="keys/ctfbuilder_ed25519"
PORT=2201
HOST="ctfbuilder@127.0.0.1"
SSH_OPTS=(-i "$KEY" -p "$PORT" -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10)

DISK="disks/noob-orientation.qcow2"
OUT_DIR="dist"
OUT_IMAGE="$OUT_DIR/noob-orientation-ctf.qcow2"

if [ ! -f "$DISK" ]; then
  echo "Missing $DISK. Build the VM first." >&2
  exit 1
fi

echo "== Resetting to a never-played state (stop stack, wipe .env) =="
ssh "${SSH_OPTS[@]}" "$HOST" '
set -e
sudo systemctl stop ctf-box.service || true
cd /opt/box && sudo docker compose down -v || true
sudo rm -f /opt/box/.env
'

echo "== Stopping the VM (export needs the disk's write lock) =="
./scripts/stop-vm.sh

echo "== Snapshotting this clean, never-played state =="
qemu-img snapshot -d clean-start "$DISK" 2>/dev/null || true
qemu-img snapshot -c clean-start "$DISK"

mkdir -p "$OUT_DIR"
echo "== Flattening the clean-start snapshot into a standalone image =="
echo "   (merges base image + overlay + snapshot into one self-contained"
echo "    file -- can take a few minutes)"
rm -f "$OUT_IMAGE"
qemu-img convert -l clean-start -O qcow2 -c "$DISK" "$OUT_IMAGE"

echo "== Checksumming =="
(cd "$OUT_DIR" && sha256sum "$(basename "$OUT_IMAGE")" > SHA256SUMS)

echo "== Restarting the source VM (for any further work on this box) =="
./scripts/boot-vm.sh

echo
echo "Done. Next: ./scripts/export-ova.sh"
ls -lh "$OUT_DIR"
